#include "assets.hpp"
#include <Native/HeapPlacement.hpp>
#include <Native/JasStreamEndian.hpp>
#include <cstdio>
int main(int argc,char**argv){try{assetCheck(argc==2,"Expected WBFS");WiiAssets disc(std::filesystem::u8path(argv[1]));unsigned count=0;for(const auto&file:disc.files){if(file.path.rfind("/AudioRes/Stream/",0))continue;extent(0,64,file.size);auto bytes=disc.read(file.offset,64);JASAramStream::Header h{};assetCheck(Native::decodeJasStreamHeader(bytes.data(),bytes.size(),h),"Retail header rejected");assetCheck(Native::validJasStreamBlockSize(h.block_size,h.format),"Retail block size invalid");const uint64_t length=32+uint64_t(h.block_size)*h.channels;extent(64,length,file.size);auto block=disc.read(file.offset+64,size_t(length));JASAramStream::BlockHeader bh{};assetCheck(Native::decodeJasStreamBlock(block.data(),block.size(),h.channels,h.block_size,bh),"Retail first block rejected");const uint64_t samples=h.format==0?(uint64_t(h.block_size)*16)/9:h.block_size/2;const uint64_t last=(h.loop_end-1)/samples,start=h.loop_start/samples;assetCheck(start<=last,"Loop block range invalid");const uint64_t lastOffset=64+last*length;extent(lastOffset,32,file.size);const uint64_t finalSize=file.size-lastOffset;assetCheck(finalSize<=length,"Retail final block exceeds nominal extent");auto finalBlock=disc.read(file.offset+lastOffset,size_t(finalSize));JASAramStream::BlockHeader tail{};if(!Native::decodeJasStreamBlock(finalBlock.data(),finalBlock.size(),h.channels,h.block_size,tail)){std::fprintf(stderr,"%s finalSize=%llu payload=%u channels=%u end=%d last=%llu\n",file.path.c_str(),(unsigned long long)finalSize,be32(finalBlock.data()+4),h.channels,h.loop_end,(unsigned long long)last);throw std::runtime_error("Retail final block rejected");}assetCheck(uint64_t(tail._4)*h.channels+32==finalSize,"Retail final block unexplained trailing bytes");std::printf("%s channels=%u format=%u rate=%d block=%u tag=%08x\n",file.path.c_str(),h.channels,h.format,h._10,h.block_size,bh.tag);++count;}assetCheck(count==74,"Expected 74 streams");std::printf("PASS %u retail stream headers, first and final blocks\n",count);}catch(const std::exception&e){std::fprintf(stderr,"%s\n",e.what());return 1;}}


